"""Deterministic generator of the performance fixtures (SPEC 7.6).

Usage::

    python make_perf_fixtures.py [--out DIR]

Without ``--out`` the six files are written next to this script (the committed
copies). The module is stdlib-only and imports no product code, so the
fixtures cannot drift with the product; importing it has no side effects.

Files written:

* ``perf_ccf_301.json``            301-node tree, ten beta groups G1..G10
* ``perf_alpha_301.json``          same tree, five staggered alpha groups A1..A5
* ``perf_ccf_301_nogroups.json``   the beta file minus ``ccfGroups`` / ``fileFormatVersion``
* ``perf_alpha_301_nogroups.json`` the alpha file minus the same keys
* ``perf_grid_500.json``           25 OR gates x 20 rate events (526 nodes)
* ``perf_grid_500_paste.tsv``      500 rows: lambda per year, T hours, source

No timestamps and no randomness: two runs give identical bytes on Windows and
Linux (files are written with ``newline='\\n'``).
"""
import argparse
import json
import os

# ---------------------------------------------------------------------------
# Expected results of the two CCF fixtures (F0 BRIEF criterion 7).
#
# Derived during T0 and T2, not computed here: a hand-expanded copy of each tree (every
# CCF member replaced by OR(independent part, shared CCF events), the
# probabilities from SPEC 7.3: beta factor Q_ind = (1 - beta) * Q_t, shared
# event beta * Q_t; staggered alpha Q_k = alpha_k / C(m-1, k-1) * Q_t) was run
# through the 1.8.1 ``cutsets.compute`` with maxOrder 6 / maxCount 5000 /
# cutoff 1e-30. The numbers were re-derived independently by the acceptance
# tests (test_derived_counts.py) and by a reviewer:
#   beta : 92  = 72 single events + 2 x 8 + 4
#   alpha: 321 = 72 + 5 x 49 + 4
# The AND subsystems S1, S3, S5 give cut sets of order 27 or more, so the beta
# result is cut by ``order`` only (never by time, count or cutoff).
# The tests compare these constants with a fresh derivation.
# ---------------------------------------------------------------------------
EXPECTED_CCF_CUTSET_COUNT = 92  # 72 (OR subsystems S0, S2, S4 x OR modules j = 0, 2, 4, 6 x 6 single events) + 16 (8 of the 9 AND modules j = 1, 3, 5 of those subsystems, one group each: the CCF event or all independent parts = 2) + 4 (AND module (4,5) with G9 and G10: 2 x 2)
EXPECTED_CCF_TRUNCATED_BY = ["order"]
EXPECTED_ALPHA_CUTSET_COUNT = 321

FILES = [
    "perf_ccf_301.json",
    "perf_alpha_301.json",
    "perf_ccf_301_nogroups.json",
    "perf_alpha_301_nogroups.json",
    "perf_grid_500.json",
    "perf_grid_500_paste.tsv",
]

DATE = "2026-10-26"  # fixed on purpose: no clock in the generator
CUTSETS = {"maxOrder": 6, "maxCount": 5000, "cutoff": 1e-30}

# SPEC 7.6: AND modules (i, j) that hold the CCF members.
BETA_MODULES = [(0, 1), (0, 3), (0, 5), (2, 1), (2, 3), (2, 5), (4, 1), (4, 3), (4, 5)]
ALPHA_MODULES = [(0, 1), (0, 3), (0, 5), (2, 1), (2, 3)]
BETA = 0.1
ALPHA = [0.95, 0.03, 0.01, 0.01]

GRID_LAMBDA = 1e-6  # per hour
GRID_T = 8760.0  # hours
# Probability of a rate event: -expm1(-GRID_LAMBDA * GRID_T) = 1 - exp(-8.76e-3),
# the 15 significant digits of the true value. It is a literal on purpose: the last
# bit of math.expm1 differs between Python builds (3.14 on Windows gives
# ...964442, 3.10 gives ...964444), which would make the generated bytes
# depend on the interpreter. The tests compare it with rel=1e-12.
GRID_Q = 0.00872174299196444


# ---------------------------------------------------------------------------
# node builders
# ---------------------------------------------------------------------------


def gate_node(node_id, name, kind, children, type_="Event"):
    return {"id": node_id, "name": name, "type": type_, "probability": 1.0,
            "logicGate": kind, "notes": "", "links": [], "children": children}


def leaf_node(node_id, name, probability, quant):
    return {"id": node_id, "name": name, "type": "Event", "probability": probability,
            "logicGate": "OR", "notes": "", "links": [], "children": [], "quant": quant}


def tree_301(member_ids):
    """SPEC 7.6 base tree: 1 + 6 + 42 + 252 nodes. Components in ``member_ids``
    get q = 1e-3, every other component q = 1e-3 * (m + 1)."""
    members = set(member_ids)
    subsystems = []
    for i in range(6):
        modules = []
        for j in range(7):
            comps = []
            for m in range(6):
                cid = "C%d_%d_%d" % (i, j, m)
                q = 1e-3 if cid in members else 1e-3 * (m + 1)
                comps.append(leaf_node(cid, "Component %d.%d.%d" % (i, j, m), q,
                                       {"model": "fixed"}))
            modules.append(gate_node("M%d_%d" % (i, j), "Module %d.%d" % (i, j),
                                     "AND" if (i + j) % 2 else "OR", comps))
        subsystems.append(gate_node("S%d" % i, "Subsystem %d" % i,
                                    "AND" if i % 2 else "OR", modules))
    return gate_node("root", "Top event", "OR", subsystems, type_="Root")


def beta_groups():
    groups = []
    for k, (i, j) in enumerate(BETA_MODULES):
        groups.append(("G%d" % (k + 1), ["C%d_%d_%d" % (i, j, m) for m in range(3)]))
    groups.append(("G10", ["C4_5_3", "C4_5_4", "C4_5_5"]))
    out = []
    for gid, members in groups:
        out.append({"id": gid, "name": "Feed pumps " + gid, "model": "beta",
                    "beta": BETA, "alpha": None, "testing": None,
                    "members": members, "source": "perf fixture, beta 0.1"})
    return out


def alpha_groups():
    out = []
    for k, (i, j) in enumerate(ALPHA_MODULES):
        gid = "A%d" % (k + 1)
        out.append({"id": gid, "name": "Feed pumps " + gid, "model": "alpha",
                    "beta": None, "alpha": list(ALPHA), "testing": "staggered",
                    "members": ["C%d_%d_%d" % (i, j, m) for m in range(4)],
                    "source": "perf fixture, staggered alpha"})
    return out


def document_301(title, groups):
    members = [m for g in groups for m in g["members"]]
    return {"title": title, "date": DATE, "mode": "FTA", "tree": tree_301(members),
            "analysis": {"cutsets": dict(CUTSETS)}}


def with_groups(document, groups):
    """Same document plus ``analysis.ccfGroups`` and ``fileFormatVersion``."""
    out = {"title": document["title"], "date": document["date"],
           "mode": document["mode"], "fileFormatVersion": 2, "tree": document["tree"],
           "analysis": dict(document["analysis"], ccfGroups=groups)}
    return out


def grid_document():
    q = GRID_Q
    gates = []
    for gg in range(25):
        events = [leaf_node("E%02d_%02d" % (gg, nn), "Event %02d.%02d" % (gg, nn), q,
                            {"model": "rate", "lambda": GRID_LAMBDA, "T": GRID_T})
                  for nn in range(20)]
        gates.append(gate_node("G%02d" % gg, "Group %02d" % gg, "OR", events))
    return {"title": "Performance grid 500", "date": DATE, "mode": "FTA",
            "tree": gate_node("root", "Top event", "OR", gates, type_="Root"),
            "analysis": {}}


def paste_text():
    """500 rows in tree order (E00_00 .. E24_19): lambda per year, T hours, source.

    The values are deterministic functions of the row index i, so pasting them
    changes most rows (the grid stores 1e-6 /h = 8.76e-3 /y, T = 8760 h):
    lambda_y = 8.76e-3 * (1 + (i % 7) / 10) written with %.6g (only i % 7 == 0
    repeats the stored value), T = 8760, source = 'perf-E<gg>_<nn>'.
    """
    lines = []
    for i in range(500):
        gg, nn = divmod(i, 20)
        lam_y = 8.76e-3 * (1 + (i % 7) / 10)
        lines.append("%s\t%d\t%s" % ("%.6g" % lam_y, 8760, "perf-E%02d_%02d" % (gg, nn)))
    return "\n".join(lines) + "\n"


# ---------------------------------------------------------------------------
# output
# ---------------------------------------------------------------------------


def dump_json(document):
    return json.dumps(document, indent=2, ensure_ascii=False) + "\n"


def build_all():
    """name -> text for the six files."""
    beta, alpha = beta_groups(), alpha_groups()
    beta_ng = document_301("Performance 301 beta CCF", beta)
    alpha_ng = document_301("Performance 301 alpha CCF", alpha)
    return {
        "perf_ccf_301.json": dump_json(with_groups(beta_ng, beta)),
        "perf_alpha_301.json": dump_json(with_groups(alpha_ng, alpha)),
        "perf_ccf_301_nogroups.json": dump_json(beta_ng),
        "perf_alpha_301_nogroups.json": dump_json(alpha_ng),
        "perf_grid_500.json": dump_json(grid_document()),
        "perf_grid_500_paste.tsv": paste_text(),
    }


def write_all(out_dir):
    os.makedirs(out_dir, exist_ok=True)
    for name, text in build_all().items():
        with open(os.path.join(out_dir, name), "w", newline="\n", encoding="utf-8") as handle:
            handle.write(text)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Write the performance fixtures.")
    parser.add_argument("--out", default=os.path.dirname(os.path.abspath(__file__)),
                        help="output folder (default: the folder of this script)")
    args = parser.parse_args(argv)
    write_all(args.out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
